        case, threads = observation['case'], observation['threads']
        actions = []
        for sid in observation['ready_suppliers']:
            events = threads[sid]
            offer_id, terms = standing(events)
            if latest(events).get('status') in ('agreed', 'final_offer') or moves_left(case, events) <= 0:
