                return {'actions': [{'supplier_id': sid, 'message': {'action': {'type': 'accept',
                                         'term_sheet_id': offer_id}}}], 'state': state}
            actions.append({'supplier_id': sid, 'message': {
                'subject': case['title'], 'body': 'Thank you. Could you improve this package?',
                'term_sheets': [{'terms': complete_offer(case, {**terms, 'unit_price': terms['unit_price'] * .95})}]}})
        return {'actions': actions, 'state': state}


