"""One validation/closing policy for every agent, timeout and error path."""

import math

from ..cost import must_haves_ok, total_cost
from ..docs import quote_terms, standard_terms
from ..play import live_threads, standing
from .state import encode


def documented(events):
    for msg in reversed(events):
        for att in msg.get("attachments") or []:
            if att.get("name", "").startswith("quote"):
                try:
                    return bool(quote_terms(att.get("text", "")).get("stated")) and not att.get("error")
                except (ValueError, TypeError):
                    return False
    return False


def acceptable(case, events):
    offer_id, terms = standing(events)
    std = standard_terms(events)
    if not offer_id or not documented(events):
        return False
    if any(f not in terms and f not in std and f not in case.get("fixed_terms", {}) for f in case["negotiable"]):
        return False
    try:
        cost = total_cost(case, terms, std)
        alt = case["buyer"].get("alternative") or {}
        limit = (
            total_cost(case, alt["terms"]) if alt.get("kind") not in (None, "none") and alt.get("terms") else math.inf
        )
        return math.isfinite(cost) and must_haves_ok(case, terms, std) and cost <= limit
    except (ValueError, TypeError, KeyError, ZeroDivisionError):
        return False


def close_action(case, threads):
    live = live_threads(threads)
    candidates = []
    for sid in live:
        if acceptable(case, threads[sid]):
            offer_id, terms = standing(threads[sid])
            candidates.append((total_cost(case, terms, standard_terms(threads[sid])), sid, offer_id))
    if candidates:
        _, sid, offer_id = min(candidates)
        return {"supplier_id": sid, "message": {"action": {"type": "accept", "term_sheet_id": offer_id}}}
    sid = (live or list(threads))[0]
    return {"supplier_id": sid, "message": {"action": {"type": "walk_away"}}}


def validate(case, threads, actions):
    if not isinstance(actions, list) or not actions or len(actions) > len(threads):
        raise ValueError("Agent must return a nonempty list of actions")
    seen = set()
    for action in actions:
        if set(action) != {"supplier_id", "message"}:
            raise ValueError("Action must contain supplier_id and message")
        sid, message = action["supplier_id"], action["message"]
        if sid not in live_threads(threads) or sid in seen:
            raise ValueError("Unknown, closed or duplicate supplier")
        seen.add(sid)
        if not isinstance(message, dict) or set(message) - {
            "subject",
            "body",
            "term_sheets",
            "refs",
            "attachments",
            "action",
            "thread_id",
            "message_id",
            "in_reply_to",
        }:
            raise ValueError("Invalid message fields")
        if len(encode({"message": message}).encode()) > 64 * 1024:
            raise ValueError("Message too large")
        if message.get("action"):
            cmd = message["action"]
            if len(actions) != 1 or cmd.get("type") not in ("accept", "walk_away"):
                raise ValueError("Closing must be the only action")
            if cmd["type"] == "accept":
                if set(cmd) != {"type", "term_sheet_id"}:
                    raise ValueError("Invalid accept")
                if cmd["term_sheet_id"] != standing(threads[sid])[0] or not acceptable(case, threads[sid]):
                    raise ValueError("Unsafe or stale acceptance")
            elif set(cmd) != {"type"}:
                raise ValueError("Invalid walk_away")
            continue
        for field, size in (("subject", 300), ("body", 8000)):
            if not isinstance(message.get(field, ""), str) or len(message.get(field, "")) > size:
                raise ValueError(f"Invalid {field}")
        refs = message.get("refs", [])
        if not isinstance(refs, list) or len(refs) > 20 or any(not isinstance(x, str) for x in refs):
            raise ValueError("Invalid refs")
        attachments = message.get("attachments", [])
        if not isinstance(attachments, list) or len(attachments) > 5:
            raise ValueError("Invalid attachments")
        import base64

        for att in attachments:
            if set(att) != {"name", "type", "content_b64"} or att["type"] not in ("md", "csv", "json", "pdf", "xlsx"):
                raise ValueError("Invalid attachment")
            base64.b64decode(att["content_b64"], validate=True)
        sheets = message.get("term_sheets", [])
        if not isinstance(sheets, list) or len(sheets) > 3:
            raise ValueError("At most three term sheets")
        std = standard_terms(threads[sid])
        for sheet in sheets:
            if set(sheet) != {"terms"} or set(sheet["terms"]) != set(case["negotiable"]):
                raise ValueError("Term sheets require exactly the negotiable fields")
            for field, value in sheet["terms"].items():
                if isinstance(value, float) and not math.isfinite(value):
                    raise ValueError("Non-finite term")
                if field == "unit_price":
                    if (
                        isinstance(value, bool)
                        or not isinstance(value, int | float)
                        or value <= 0
                        or round(value, 2) != value
                    ):
                        raise ValueError("Price must be positive with at most two decimals")
                elif value not in case.get("term_options", {}).get(field, []) and value != std.get(field):
                    raise ValueError(f"Term outside allowed options: {field}")
    return actions
"""Results from our sessions only; no scoreboard access."""

import json
from collections import Counter


def report(journal):
    cfg = journal.get("config")
    cases = journal.cases()
    rows = []
    for cid, case in cases.items():
        result = case.get("result") or {}
        rows.append(
            {
                "case_id": cid,
                "case_hash": case.get("case_hash"),
                "wave": case.get("case", {}).get("wave"),
                "session_id": case.get("session_id"),
                "error": case.get("error"),
                "end_reason": case.get("end_reason"),
                "rounds": case.get("rounds"),
                **result,
            }
        )
    complete = [r for r in rows if isinstance(r.get("score"), int | float)]
    events = [
        dict(r) | {"value": json.loads(r["value"])} for r in journal.db.execute("SELECT * FROM events ORDER BY n")
    ]
    calls = [dict(r) for r in journal.db.execute("SELECT * FROM model_calls")]
    thread_timeouts = {}
    for event in events:
        if event["kind"] == "thread_state":
            value = event["value"]
            key = (value["session"], value["supplier"])
            thread_timeouts[key] = max(thread_timeouts.get(key, 0), value["timeouts"])
    tokens = Counter()
    for call in calls:
        tokens.update({k: v for k, v in json.loads(call["usage"] or "{}").items() if isinstance(v, int)})

    def latency(kind):
        values = sorted(e["value"]["elapsed"] for e in events if e["kind"] == kind and "elapsed" in e["value"])
        return {
            "count": len(values),
            "mean": sum(values) / len(values) if values else None,
            "p95": values[min(len(values) - 1, int(0.95 * len(values)))] if values else None,
        }

    score = sum(r["score"] for r in complete) / len(complete) if complete else None
    unknown_calls = sum(c["status"] != "done" or not json.loads(c["usage"] or "{}") for c in calls)
    model = cfg["model"]
    estimate = None
    if all(k in model for k in ("input_usd_per_million", "output_usd_per_million")):
        estimate = (
            tokens["prompt_tokens"] * model["input_usd_per_million"]
            + tokens["completion_tokens"] * model["output_usd_per_million"]
        ) / 1e6
    wave_points = {}
    if cfg["profile"] == "final":
        for wave in sorted({r["wave"] for r in rows if r.get("wave") is not None}):
            group = [r for r in rows if r["wave"] == wave]
            wave_points[wave] = (
                round(100 * sum(r["score"] for r in group) / len(group), 1)
                if all(isinstance(r.get("score"), int | float) for r in group)
                else None
            )
    return {
        "run_id": journal.folder.name,
        "status": journal.get("status", "running"),
        "profile": cfg["profile"],
        "agent": cfg["agent"],
        "model": model.get("name"),
        "source": cfg["source"],
        "config_hash": cfg["config_hash"],
        "data_hash": cfg["data_hash"],
        "agent_hash": cfg["agent_hash"],
        "selected": len(rows),
        "scored": len(complete),
        "coverage": len(complete) / len(rows) if rows else 0,
        "mean_score_completed": score,
        "complete_score": score if rows and len(complete) == len(rows) else None,
        "wave_points": wave_points,
        "final_points": sum(wave_points.values())
        if len(wave_points) == 5 and all(v is not None for v in wave_points.values())
        else None,
        "deals": sum(bool(r.get("deal")) for r in rows),
        "fallbacks": sum(e["kind"] == "fallback" for e in events),
        "timeouts": sum(e["kind"] == "fallback" and e["value"].get("reason") == "TimeoutError" for e in events),
        "arena_timeouts_observed": sum(thread_timeouts.values()),
        "retries": sum(e["kind"] == "api" and e["value"].get("retry", False) for e in events),
        "claims": dict(
            Counter(c["result"] for e in events if e["kind"] == "reply" for c in e["value"].get("claims", []))
        ),
        "decision_seconds": latency("decision"),
        "api_seconds": latency("api"),
        "model_calls": len(calls),
        "usage_tokens": dict(tokens),
        "unknown_usage_calls": unknown_calls,
        "estimated_usd_known_usage": estimate,
        "cases": rows,
    }


def compare(reports, allow_mismatch=False):
    if len(reports) < 2:
        raise ValueError("Compare needs at least two runs")
    if len({r["profile"] for r in reports}) != 1:
        raise ValueError("Different execution profiles cannot be compared")
    common = set.intersection(*[{c["case_id"] for c in r["cases"]} for r in reports])
    indexes = [{c["case_id"]: c for c in r["cases"]} for r in reports]
    mismatch = len({r["data_hash"] for r in reports}) > 1 or any(
        len({c["case_id"] for c in r["cases"]}) != len(common) for r in reports
    )
    mismatch |= any(len({i[cid]["case_hash"] for i in indexes}) > 1 for cid in common)
    if mismatch and not allow_mismatch:
        raise ValueError("Case/data sets differ; --allow-mismatch produces a restricted comparison")
    rows = []
    for cid in sorted(common):
        scores = [i[cid].get("score") for i in indexes]
        rows.append(
            {
                "case_id": cid,
                "scores": scores,
                "deltas_from_first": [
                    s - scores[0] if s is not None and scores[0] is not None else None for s in scores
                ],
            }
        )
    return {
        "runs": [r["run_id"] for r in reports],
        "restricted": bool(mismatch),
        "cases": rows,
        "mean_paired_scores": [
            sum(row["scores"][n] for row in rows) / len(rows)
            if rows and all(row["scores"][n] is not None for row in rows)
            else None
            for n in range(len(reports))
        ],
    }
